code.formula:
@Command([EditDocument];"1");

@If(Company = "";@Return(@Do(@Command([EditGotoField];"Company");@Prompt([Ok];"Alert!";"Please select the company!")));"");
@If(Dept = "";@Return(@Do(@Command([EditGotoField];"Dept");@Prompt([Ok];"Alert!";"Please select the department!")));"");
@If(Area = "";@Return(@Do(@Command([EditGotoField];"Area");@Prompt([Ok];"Alert!";"Please select the area!")));"");
@If(BusinessArea = "";@Return(@Do(@Command([EditGotoField];"BusinessArea");@Prompt([Ok];"Alert!";"Please select the business area!")));"");
@If(AuditorName="";@Return(@Do(@Command([EditGotoField];"AuditorName");@Prompt([Ok];"Alert!";"Please state the Auditor Name!")));"");
@If(Auditee="";@Return(@Do(@Command([EditGotoField];"AuditeeName");@Prompt([Ok];"Alert!";"Please select the Auditee!")));"");
@If(AuditeeName="";@Return(@Do(@Command([EditGotoField];"AuditeeName");@Prompt([Ok];"Alert!";"Please state the Auditee Name!")));"");
@If(AuditeeHOD="";@Return(@Do(@Command([EditGotoField];"AuditeeHOD");@Prompt([Ok];"Alert!";"Please select the Auditee's HOD!")));"");
@If(isFinding ="";@Return(@Do(@Command([EditGotoField];"isFinding");@Prompt([Ok];"Alert!";"Please state if any finding is found!")));"");
@If(isFinding ="Yes" & Finding_1 ="";@Return(@Do(@Command([EditGotoField];"Finding_1");@Prompt([Ok];"Alert!";"Please state the finding statements!")));"");

FIELD CA 				:= "Submitted";
FIELD ReqDate		:= @Now;
FIELD ReqName		:= @V3UserName;
FIELD RemDate:= @Adjust(@Today;0;0;5;0;0;0);

@Command([FileSave]);
@MailSend(AuditeeHOD;Defcc:CC;NULL;@DbTitle+" - New - " + @Trim(DocNo);NULL;"Please follow this doclink ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

